package com.nsp.launcher;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.view.*;import android.widget.*;import java.util.*;
public class NewsActivity extends Activity{
 LinearLayout list; TextView title; int cat=0; ArrayList<RssItem>items=new ArrayList<RssItem>();
 public void onCreate(Bundle b){super.onCreate(b); LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(24,12,24,12); root.setBackgroundColor(Color.BLACK);title=new TextView(this);title.setTextSize(25);title.setTextColor(Color.WHITE);root.addView(title);TextView hint=new TextView(this);hint.setText("← → categoría  |  ↑ ↓ titular  |  A detalle/abrir  |  B volver");hint.setTextSize(10);hint.setTextColor(0xffaaaaaa);root.addView(hint);ScrollView s=new ScrollView(this);list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);s.addView(list);root.addView(s,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);load();}
 void load(){title.setText("NOTICIAS · "+RssService.NAMES[cat]+"  Cargando...");list.removeAllViews();RssService.load(cat,new RssService.Callback(){public void done(ArrayList<RssItem>x){items=x;title.setText("NOTICIAS · "+RssService.NAMES[cat]);if(x.isEmpty()){TextView e=row("Sin noticias o sin conexión",null);list.addView(e);}for(final RssItem i:x)list.addView(row(i.title,i));}});}
 TextView row(String s,final RssItem i){TextView v=new TextView(this);v.setText(s);v.setTextSize(16);v.setTextColor(Color.WHITE);v.setPadding(12,14,12,14);v.setFocusable(true);v.setOnClickListener(new View.OnClickListener(){public void onClick(View z){if(i!=null)detail(i);}});return v;}
 void detail(final RssItem i){new AlertDialog.Builder(this).setTitle(i.source).setMessage(i.title+"\n\n"+(i.description==null?"":i.description.replaceAll("<[^>]+>",""))).setPositiveButton("Abrir",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){try{startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse(i.link)));}catch(Exception e){}}}).setNegativeButton("Volver",null).show();}
 public boolean dispatchKeyEvent(KeyEvent e){if(e.getAction()==KeyEvent.ACTION_DOWN&&(e.getKeyCode()==KeyEvent.KEYCODE_DPAD_LEFT||e.getKeyCode()==KeyEvent.KEYCODE_DPAD_RIGHT)){cat=(cat+(e.getKeyCode()==KeyEvent.KEYCODE_DPAD_LEFT?3:1))%4;load();return true;}return super.dispatchKeyEvent(e);}
}
